package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user and a person to move the claim to. */
public class ValidateReassign {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        long personId;
        try {
            personId = Long.parseLong(request.personId() == null ? "" : request.personId().trim());
        } catch (NumberFormatException e) {
            throw new InvalidClaimException("Choose the person to move the claim to.");
        }
        body.set(new ReassignInput(request.user().trim(), personId));
    }
}
package net.officefloor.hq.app.claim;

/** A validated reassign: who is making it and the id of the person the claim moves to. */
public record ReassignInput(String user, long personId) {
}
package net.officefloor.hq.app.claim;

/** Body of a reassign: who is making it and the id of the person the claim moves to. */
public record ReassignRequest(String user, String personId) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;

/** Moving one claim to another person, shared by a single move and a bulk one (see {@link SaveReassign}). */
final class ClaimReassign {
    private ClaimReassign() {
    }

    /** Move the claim by the rules of {@link SaveReassign}, answering it as moved. A numbered claim takes the next number in the
     *  sequence it would be numbered in now (its old one is never used again); a draft stays unnumbered. A bulk move ({@code bulk}) also lets a claim
     *  "move" to the person it already belongs to: it is written (losing any statement figure) and audited as a
     *  move like any other. */
    public static ClaimResponse move(ReassignInput input, Claim loaded, ClaimRepository repository,
            PersonRepository people, RoleRepository roles, SettingRepository settings, boolean bulk)
            throws ClaimStatusNotAllowedException, PersonNotFoundException, RetiredPersonException {
        if (!settings.permissions(loaded.sheetId()).allows("reassign", roles.of(loaded.sheetId(), input.user()))) {
            throw new ClaimStatusNotAllowedException("Your role may not move a claim to another person on this sheet.");
        }
        if (!loaded.status().unsettled() && loaded.status() != ClaimStatus.DRAFT) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot move; only a DRAFT, OPEN or PENDING one can.");
        }
        if (loaded.corrects() != null && loaded.status() != ClaimStatus.DRAFT) {
            throw new ClaimStatusNotAllowedException("A correction cannot move to another person once it is opened.");
        }
        Person to = people.find(loaded.sheetId(), input.personId());
        if (to == null) {
            throw new PersonNotFoundException(String.valueOf(input.personId()));
        }
        if (!bulk && to.id() == loaded.personId()) {
            throw new ClaimStatusNotAllowedException("The claim is already " + to.name() + "'s.");
        }
        RetiredPersonException.refuse(to, loaded.date());
        String number = loaded.number() != null ? repository.nextNumber(loaded.sheetId(), loaded.dueBy()) : null;
        if (!repository.reassign(loaded, to.id(), number)) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        return ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), to.id(), loaded.amount(),
                loaded.date(), loaded.note(), loaded.status(), number, loaded.settledDue(),
                loaded.openedBy(), false, null, loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(),
                loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), loaded.ref(), loaded.tags(), loaded.waived(), loaded.photos(), loaded.held()));
    }

    /** The CLAIM_REASSIGNED line: the claim like every claim line (with its new person), then the person it moved
     *  from and to. */
    public static void audit(ReassignInput input, Claim loaded, ClaimResponse saved, PersonRepository people,
            Audit audit) {
        var from = people.find(loaded.sheetId(), loaded.personId());
        var to = people.find(loaded.sheetId(), saved.personId());
        audit.record("CLAIM_REASSIGNED sheet=" + loaded.sheetId() + " by=" + input.user()
                + " person=" + to.name() + " amount=" + saved.amount() + " date=" + saved.date()
                + (saved.number() != null ? " number=" + saved.number() : "")
                + " from=" + from.name() + " to=" + to.name());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Move the loaded claim to another person on the sheet. Only a role the sheet's permission matrix lets reassign
 *  may (by default a steward), and only a DRAFT, OPEN or PENDING
 *  claim that is not an opened correction (a correction names a claim of its own person; a DRAFT one may still move), to another person it may be
 *  dated for (not retired before its date). It keeps its date; a numbered claim takes the next number in the sequence it would be numbered in now (the sheet's, or its period's), its old one never used again, and a draft stays unnumbered. It loses any figure a statement bound
 *  it to: its due is live again until its new person's next statement. A move another user's change got to first
 *  is refused. */
public class SaveReassign {
    public void save(@Val ReassignInput input, @Val Claim loaded, ClaimRepository repository,
            PersonRepository people, RoleRepository roles, SettingRepository settings, Out<ClaimResponse> saved)
            throws ClaimStatusNotAllowedException, PersonNotFoundException, RetiredPersonException {
        saved.set(ClaimReassign.move(input, loaded, repository, people, roles, settings, false));
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.claim.ReassignInput;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Record, after the change's own lines, how the sheet's figures moved over it. */
public class AuditReassignRollup {
    public void audit(@PathVariable("sheetId") String sheetId, @Val ReassignInput request, @Val Rollup before,
            Rollups rollups) {
        rollups.record(sheetId.trim(), request.user(), before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the claim is not on the sheet. */
public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimRepository repository, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found = null;
        try {
            found = repository.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (found == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claim.set(found);
    }
}

